const minionId = msg.payload.minionId || 'Unknown Minion';
const timestamp = msg.uyuni ? msg.uyuni.timestamp : new Date().toISOString();

msg.headers = {
    'Content-Type': 'application/json'
};

msg.payload = {
    text: `🚨 *Uyuni Alert*: Minion *${minionId}* has registered!`,
    blocks: [
        {
            type: 'header',
            text: { type: 'plain_text', text: '🔔 Uyuni Minion Registration Alert' }
        },
        {
            type: 'section',
            fields: [
                { type: 'mrkdwn', text: `*Minion ID:*\n${minionId}` },
                { type: 'mrkdwn', text: `*Timestamp:*\n${timestamp}` }
            ]
        }
    ]
};

return msg;
